// random 1D to 1D
float random11(float t) {
    return fract(sin(t * 12.34) * 567.89);
}

// random 2D to 1D
float random21(vec2 st) {
    return fract(sin(dot(st.xy, vec2(123.45, 67.89))) * 98765.4321);
}

// random 2D to 2D
vec2 random2(vec2 st){
    st = vec2(dot(st, vec2(127.1, 311.7)),
              dot(st, vec2(269.5, 183.3)) );
    return -1.0 + 2.0 * fract(sin(st) * 43758.5453123);
}

// rotation matrix
mat2 rot1 = mat2(4., -3., 4., 3.) / 5.;

// Gradient Noise by Inigo Quilez - iq/2013
// https://www.shadertoy.com/view/XdXGW8
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    vec2 u = f*f*(3.0-2.0*f);

    return mix( mix( dot( random2(i + vec2(0.0,0.0) ), f - vec2(0.0,0.0) ),
                     dot( random2(i + vec2(1.0,0.0) ), f - vec2(1.0,0.0) ), u.x),
                mix( dot( random2(i + vec2(0.0,1.0) ), f - vec2(0.0,1.0) ),
                     dot( random2(i + vec2(1.0,1.0) ), f - vec2(1.0,1.0) ), u.x), u.y);
}

//  Function from Iñigo Quiles
//  https://www.shadertoy.com/view/MsS3Wc
vec3 hsb2rgb( in vec3 c ){
    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                             6.0)-3.0)-1.0,
                     0.0,
                     1.0 );
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

float blob_sdf(vec2 uv, float r) {

    float d = length(uv); // radius from 0,0
    vec2 n = uv / d; // normalized for a clear direction for the noise offset

    float magnitude = .5;
    float frequency = .5;
    vec2 t = vec2(iTime) * 0.5;

    float offset = noise(t + frequency * n);// 
    d += magnitude * offset;
    return d - r;
}

vec3 hsb_noise(vec2 uv, float hue) {
    vec3 color = vec3(0.0);

    float s = 1.57;
    for (int i = 0; i < 7; i++) 
    {
        uv = uv * rot1 * 2.23;
        color += hsb2rgb(vec3(hue, 
            noise(uv * 0.3) * 0.5 + 0.45, 
            noise(uv * 0.712) * 0.2 + 0.8)) / s;
        s *= 2.03;
        uv += iTime * .25;
    }
    return color;
}

float hue = 0.73; 

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // pixel coordinates (from -1 to 1 in a centered square)
    // compensating for aspect ratio, coordinates outside -1..1 for the longer axis
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y) * 2.;

    // vary main hue
    vec2 hue_line = vec2(0.123, 0.2345);
    hue = fract(uv.x * hue_line.x + uv.y * hue_line.y + 0.1 * iTime);
    // flipp hue across an oscillating line
    hue = fract(hue + 0.5 * smoothstep(-0.001, 0.001, 
        uv.x * -hue_line.y * 1.73 
        + uv.y * hue_line.x
        + 0.2 * sin(iTime * 0.8)));

    // layered hsb noise
    vec3 color = hsb_noise(uv, hue);
    //color = hsb2rgb(vec3(hue, 1., 1.));

    // blob shape sdf
    float r = blob_sdf(uv, 0.75);
    float t = 0.0;

    // get darker closer to the border
    t = smoothstep(-0.2, 0.1, r);
    color *= 1. - 0.15 * t;

    // blend the circle/blob with the background
    t = smoothstep(-0.01, 0.0, r);
    color = mix(color, vec3(0.97, 0.95, 0.93), t);

    // output to screen
    fragColor = vec4(color, 1.0);
}
